package hexadecimal

import (
	"errors"
	"fmt"
	"math"
	"strings"
)

// ParseHex converts a hexadecimal number, represented as a string
// (e.g. "10af8c"), to its decimal equivalent using first principles.
//
// The conversion is done by hand: each character is mapped to its
// 0-15 digit value and folded into an accumulator (result = result*16 +
// value). No built-in or external conversion library is used.
//
// It returns a "syntax" error when the input is empty or contains a
// character that is not a valid hexadecimal digit, and a "range" error
// when the value would overflow an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errors.New("syntax error: input is empty")
	}

	var result int64
	for i, c := range in {
		value, ok := hexValue(c)
		if !ok {
			return 0, fmt.Errorf("syntax error: invalid hex digit %q at position %d", c, i)
		}
		// Detect overflow before it happens: result*16+value would exceed
		// MaxInt64 exactly when result > (MaxInt64-value)/16.
		if result > (math.MaxInt64-value)/16 {
			return 0, errors.New("range error: value out of int64 range")
		}
		result = result*16 + value
	}
	return result, nil
}

// hexValue returns the decimal value of a single hexadecimal digit and
// whether the rune is a valid hexadecimal digit. Matching is
// case-insensitive (0-9, a-f, A-F).
func hexValue(c rune) (int64, bool) {
	switch {
	case c >= '0' && c <= '9':
		return int64(c - '0'), true
	case c >= 'a' && c <= 'f':
		return int64(c-'a') + 10, true
	case c >= 'A' && c <= 'F':
		return int64(c-'A') + 10, true
	default:
		return 0, false
	}
}

// HandleErrors calls ParseHex on each input and returns a matching list
// containing "none", "syntax", or "range" according to the error.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		results[i] = classify(ParseHex(in))
	}
	return results
}

// classify maps a ParseHex error to "none", "syntax", or "range" by
// inspecting the error message.
func classify(err error) string {
	if err == nil {
		return "none"
	}
	msg := strings.ToLower(err.Error())
	if strings.Contains(msg, "range") {
		return "range"
	}
	return "syntax"
}

